def _bounded_result(original):
    """Apply the same edge-ratio ceiling to the original fallback as the pattern."""
    from . import curved_quad_quality_nodes as quality
    c=boundary.c
    tree=original.copy();tree.name=original.name+' / Bounded quads';tree.nodes.clear()
    g=c.Graph.__new__(c.Graph);g.g=tree;g.count=0;g.frame=None
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    call=g.node('GeometryNodeGroup','Complete checked aggregate patch');call.node_tree=original
    for socket in call.inputs:
        if socket.name in inp.outputs:g.bind(inp.outputs[socket.name],socket)
    shape=g.node('GeometryNodeGroup','Measure all published quads, including fallback');shape.node_tree=quality.build()
    g.bind(call.outputs['Geometry'],shape.inputs['Geometry'])
    ratio=shape.outputs['Maximum Edge Ratio']
    shape_ok=1.-g.math('GREATER_THAN',ratio,quality.MAX_EDGE_RATIO)
    valid=c.V(g,call.outputs['Valid'])*shape_ok
    for socket in tree.interface.items_tree:
        if socket.item_type!='SOCKET' or socket.in_out!='OUTPUT':continue
        value=call.outputs[socket.name]
        if socket.name=='Valid':value=valid
        elif socket.name=='Geometry':value=boundary._empty(g,value,valid)
        elif socket.name=='Status':
            value=c._store(g,value,'valid',valid,'BOOLEAN')
            value=c._store(g,value,'aggregate_shape_valid',shape_ok,'BOOLEAN')
            value=c._store(g,value,'aggregate_maximum_edge_ratio',ratio)
        g.bind(value,out.inputs[socket.name])
    return tree


def _mesh_status(tree):
    """Expose upstream mesh admission so a shape rejection is not blamed on Z."""
    heights=[n for n in tree.nodes if n.type=='GROUP' and
             {'Projection Valid','Bounds Valid'}<=set(n.outputs.keys()) and
             'Input Valid' in n.inputs]
    outputs=[n for n in tree.nodes if n.type=='GROUP_OUTPUT' and n.is_active_output
             and 'Status' in n.inputs]
    if len(heights)!=1 or len(outputs)!=1:return tree
    links=list(heights[0].inputs['Input Valid'].links)
    if len(links)!=1 or links[0].from_socket.name!='Valid':return tree
    result=tree.copy();g=boundary.c.Graph.__new__(boundary.c.Graph)
    g.g=result;g.count=len(result.nodes);g.frame=None
    out=result.nodes[outputs[0].name]
    status,=out.inputs['Status'].links
    mesh=result.nodes[links[0].from_node.name]
    g.bind(boundary.c._store(g,status.from_socket,'mesh_valid',mesh.outputs['Valid'],'BOOLEAN'),out.inputs['Status'])
    return result


